import React, { useEffect, useState } from 'react';
import { totalItems } from '../lib/cart';

export default function PublicHeader(){
  const [user, setUser] = useState(null);
  const [count, setCount] = useState(0);

  useEffect(()=>{
    try{
      const userData = localStorage.getItem('hr_user');
      if (userData) setUser(JSON.parse(userData));
    }catch{}
    setCount(totalItems());
    const onUpd = ()=> setCount(totalItems());
    window.addEventListener('cart_updated', onUpd);
    return ()=> window.removeEventListener('cart_updated', onUpd);
  },[]);

  function logout(e){
    e.preventDefault();
    localStorage.removeItem('hr_token');
    localStorage.removeItem('hr_user');
    window.location.reload();
  }

  return (
    <header style={{background:'#f27171', padding:'12px 20px', color:'#000', display:'flex', justifyContent:'space-between', alignItems:'center'}}>
      <strong>HRSHOPKU BAJU BODO</strong>
      <div>
        {user ? (
          <span>Halo, {user.name} | <a href="#" onClick={logout} style={{color:'#000'}}>Logout</a></span>
        ) : (
          <span><a href="/login" style={{color:'#000', marginRight:12}}>Login</a> | <a href="/register" style={{color:'#000'}}>Register</a></span>
        )}
        <span style={{marginLeft:16}}>
          <a href="/cart" style={{color:'#000'}}>Keranjang ({count})</a>
        </span>
      </div>
    </header>
  );
}
